import {FOOD_DRINKS} from '../state/food-catalog.js';
import {CAFE_DRINK_MENU,FOOD_LABELS} from './food-controller.js';
import {TRAVELER_COUNTER_TARGET} from './traveler-counter-layout.js';

/** Small non-modal picker for the outdoor self-service counter only. */
export function createTravelerCounterUI({stage,controller,getRoom,getOrderSite=()=>null,isAllowed=()=>true,isVisible=isAllowed,onOpenChange=()=>{},doc=globalThis.document,win=globalThis.window}={}){
 const root=doc.createElement('section');root.className='traveler-counter-ui';root.hidden=true;root.setAttribute('aria-label','공항 카페');
 root.innerHTML='<button type="button" class="traveler-counter-launch" data-traveler="open" aria-expanded="false">공항 카페</button><section class="traveler-counter-panel" hidden aria-label="음료 고르기"><div class="traveler-counter-heading"><strong>공항 카페</strong><button type="button" data-traveler="close" aria-label="공항 카페 닫기">닫기</button></div><p class="traveler-counter-status" role="status" aria-live="polite"></p><label for="traveler-counter-choice">음료 고르기</label><select id="traveler-counter-choice"></select><div class="traveler-counter-actions"><button type="button" data-traveler="choose">주문하기</button><button type="button" data-traveler="collect">음식주머니에 받기</button><button type="button" data-traveler="cancel">주문 취소</button></div><p class="traveler-counter-note">받은 음료는 음식주머니에 담겨요</p></section>';
 stage.append(root);const $=s=>root.querySelector(s),panel=$('.traveler-counter-panel'),launch=$('.traveler-counter-launch'),select=$('#traveler-counter-choice'),listeners=[];let alive=true,context=null,lastOpen=false,signature='',lastClearance='';
 const listen=(target,type,fn,options)=>{target?.addEventListener(type,fn,options);listeners.push([target,type,fn,options]);};
 const siteNow=()=>{try{return getOrderSite?.()??null;}catch{return null;}};
 const current=site=>{if(getRoom()!=='courtyard'||site?.id!==TRAVELER_COUNTER_TARGET.id||site.roomId!=='courtyard'||site.surface!=='ground')return false;try{return typeof site.isCurrent!=='function'||site.isCurrent()===true;}catch{return false;}};
 function clearance(){if(!alive||root.hidden||!stage.getBoundingClientRect)return;const area=stage.getBoundingClientRect(),visible=e=>e&&!e.hidden&&e.getBoundingClientRect?.().height>0,topbar=doc.querySelector('.topbar'),tools=doc.querySelector('.scene-tools'),controls=doc.querySelector('.bottom-controls'),save=doc.querySelector('#save-status');let top=12,bottom=16;for(const e of[topbar,tools])if(visible(e))top=Math.max(top,e.getBoundingClientRect().bottom-area.top+10);for(const e of[controls,save])if(visible(e))bottom=Math.max(bottom,area.bottom-e.getBoundingClientRect().top+10);const next=Math.ceil(top)+'|'+Math.ceil(bottom);if(next!==lastClearance){lastClearance=next;root.style.setProperty('--cafe-food-top',Math.ceil(top)+'px');root.style.setProperty('--cafe-food-bottom',Math.ceil(bottom)+'px');}}
 const syncOptions=rows=>{const old=select.value,existing=[...select.options],byId=new Map(existing.map(n=>[n.value,n])),nodes=rows.map(r=>{const n=byId.get(r.id)??doc.createElement('option');if(n.value!==r.id)n.value=r.id;if(n.textContent!==r.label)n.textContent=r.label;if(n.disabled!==!!r.disabled)n.disabled=!!r.disabled;return n;});if(nodes.length!==existing.length||nodes.some((n,i)=>n!==existing[i]))select.replaceChildren(...nodes);const chosen=rows.find(r=>r.id===old)?.id??rows.find(r=>!r.disabled)?.id??'';if(select.value!==chosen)select.value=chosen;};
 function render(){if(!alive)return;const site=siteNow(),s=controller.snapshot(),o=s.operation,opened=s.open&&s.mode==='order'&&s.orderSiteId===TRAVELER_COUNTER_TARGET.id,activeContext=context==='order'&&current(site),visible=current(site)&&(!doc.hidden)&&isVisible()&&(opened||activeContext);root.hidden=!visible;root.dataset.open=String(opened);if(panel.hidden===opened)panel.hidden=!opened;if(launch.hidden===opened)launch.hidden=opened;if(lastOpen!==opened){lastOpen=opened;launch.setAttribute('aria-expanded',String(opened));onOpenChange(opened);}
  const ids=(s.enabledDrinks??CAFE_DRINK_MENU).filter(id=>Array.isArray(site?.drinkIds)?site.drinkIds.includes(id):CAFE_DRINK_MENU.includes(id));
  const rows=ids.map(id=>{const r=FOOD_DRINKS[id],appleCount=s.materials?.[r.material]??0;const label=FOOD_LABELS[id]+(r.material?' · 사과 '+r.cost+'개':' · 무료');return{id,label,disabled:!!r.material&&appleCount<r.cost};});
  const key=JSON.stringify([opened,visible,ids,rows.map(x=>x.disabled),s.notice,s.readOnly,s.paused,o?.id,o?.phase,o?.itemId]);if(key!==signature){signature=key;syncOptions(rows);const busy=o&&!['done','failed'].includes(o.phase);$('.traveler-counter-status').textContent=s.readOnly?'둘러보기 모드 · 음료는 주문하지 않아요':s.paused?'잠깐 쉬는 중이에요':s.notice||(!o?'원하는 음료를 골라요':o.phase==='preparing'?'카운터에서 음료를 준비하고 있어요':o.phase==='ready'?'준비됐어요. 받기를 눌러요':o.phase==='failed'?'다시 고르거나 취소할 수 있어요':'음료를 준비하고 있어요');select.disabled=!!busy;select.hidden=!rows.length;const choose=$('[data-traveler="choose"]');choose.disabled=s.readOnly||!rows.length||!select.value||!!select.selectedOptions[0]?.disabled||!!busy;$('[data-traveler="choose"]').textContent='주문하기';$('[data-traveler="collect"]').hidden=o?.phase!=='ready';$('[data-traveler="collect"]').disabled=s.readOnly;$('[data-traveler="cancel"]').hidden=!o||o.phase==='done';$('[data-traveler="cancel"]').disabled=false;}
  clearance();
 }
 function activate(e){const b=e.target.closest?.('[data-traveler]');if(!b||!root.contains(b)||b.disabled||doc.hidden||!isAllowed())return;const action=b.dataset.traveler;if(action==='open'){if(controller.open('order')){};}else if(action==='close')controller.close();else if(action==='cancel')controller.cancel();else if(action==='collect')controller.collect();else if(action==='choose')controller.order(select.value);render();}
 listen(doc,'keydown',e=>{const s=controller.snapshot();if(!s.open||s.mode!=='order'||s.orderSiteId!==TRAVELER_COUNTER_TARGET.id||root.hidden||!current(siteNow())||e.code!=='Escape'||e.target===select)return;e.preventDefault();e.stopImmediatePropagation();controller.close();render();},true);
 listen(root,'click',activate);listen(select,'change',render);listen(win,'blur',()=>{controller.suspend('blur');render();});listen(win,'focus',()=>{if(!doc.hidden){controller.resume();render();}});listen(doc,'visibilitychange',()=>{doc.hidden?controller.suspend('hidden'):controller.resume();render();});listen(win,'pagehide',()=>{controller.suspend('pagehide');render();});listen(win,'resize',clearance);listen(win?.visualViewport,'resize',clearance);listen(win?.visualViewport,'scroll',clearance);
 return {root,render,update({context:next=null}={}){context=next;render();},dispose(){if(!alive)return;alive=false;for(const[t,n,f,o]of listeners)t?.removeEventListener(n,f,o);root.remove();}};
}
